CREATE TABLE falhas_recepcao (remessa_id INTEGER NOT NULL, cenario TEXT NOT NULL, ug TEXT NOT NULL, geracao INTEGER NOT NULL CHECK(geracao>=0), assunto TEXT NOT NULL CHECK(assunto IN ('CADASTRO_CONTRIBUINTE','LANCAMENTO_CREDITO_TRIBUTARIO','DIARIO_ARRECADACAO','BAIXA_CREDITO_TRIBUTARIO','SALDO_INICIAL_CREDITO_TRIBUTARIO','INICIO_PRAZO_PRESCRICIONAL')), tipo TEXT NOT NULL CHECK(tipo IN ('ANTES_ACEITACAO','APOS_COMMIT')), tentativa INTEGER NOT NULL CHECK(tentativa>0), tentativas INTEGER NOT NULL DEFAULT 0 CHECK(tentativas>=0 AND tentativas<=tentativa), consumida INTEGER NOT NULL DEFAULT 0 CHECK(consumida IN (0,1)), recuperacao INTEGER NOT NULL DEFAULT 0 CHECK(recuperacao IN (0,1)), PRIMARY KEY(remessa_id,assunto,geracao), FOREIGN KEY(remessa_id,cenario,ug) REFERENCES remessas(id,cenario,ug));
PRAGMA user_version=12;
